import [printf] from "std/c.bpl";

frame addWithAsm(a: int, b: int) ret int {
    local result: int = 0;

    # Intel syntax: destination, source
    asm("intel") {
        mov eax, (a)          # Load a into eax
        add eax, (b)          # Add b to eax
        mov (=result), eax    # Store eax in result
    }

    return result;
}

frame main() ret int {
    local x: int = 10;
    local y: int = 25;

    local sum: int = addWithAsm(x, y);
    printf("%d + %d = %d\n", x, y, sum);

    # Another example
    printf("100 + 50 = %d\n", addWithAsm(100, 50));

    return 0;
}

import [printf] from "std/c.bpl";

frame multiplyATT(a: int, b: int) ret int {
    local result: int = 0;

    # AT&T syntax: source, destination (opposite of Intel!)
    asm("att") {
        movl (a), %eax        # Load a into eax
        imull (b), %eax       # Multiply eax by b
        movl %eax, (=result)  # Store result
    }

    return result;
}

frame main() ret int {
    printf("6 * 7 = %d\n", multiplyATT(6, 7));
    printf("12 * 11 = %d\n", multiplyATT(12, 11));

    return 0;
}

import [printf] from "std/c.bpl";

# Using LLVM IR for precise control
frame safeBitShift(value: int, shift: int) ret int {
    local result: int = 0;

    # LLVM IR gives maximum control
    asm("llvm") {
        "%shifted = shl i32 (value), (shift)"
        "store i32 %shifted, i32* (=result)"
    }

    return result;
}

frame main() ret int {
    printf("1 << 0 = %d\n", safeBitShift(1, 0));
    printf("1 << 1 = %d\n", safeBitShift(1, 1));
    printf("1 << 4 = %d\n", safeBitShift(1, 4));
    printf("5 << 3 = %d\n", safeBitShift(5, 3));

    return 0;
}

import [printf] from "std/c.bpl";

# Advanced: specify register constraints and clobbers
frame divide(dividend: int, divisor: int) ret int {
    local quotient: int = 0;
    local remainder: int = 0;

    asm("intel") {
        mov eax, (dividend)     # Dividend in eax
        xor edx, edx            # Clear edx (high part)
        mov ecx, (divisor)      # Divisor in ecx
        div ecx                 # eax = eax/ecx, edx = remainder
        mov (=quotient), eax    # Store quotient
        mov (=remainder), edx   # Store remainder
        [ "eax", "edx", "ecx" ] # Clobbered registers
    }

    printf("Remainder: %d\n", remainder);
    return quotient;
}

frame main() ret int {
    printf("17 / 5 = %d\n", divide(17, 5));
    printf("\n100 / 7 = %d\n", divide(100, 7));

    return 0;
}

import [printf] from "std/c.bpl";

# Count leading zeros (useful for log2)
frame countLeadingZeros(n: int) ret int {
    local result: int = 0;

    if (n == 0) {
        return 32;  # All zeros
    }

    asm("intel") {
        bsr eax, (n)          # Bit scan reverse
        xor eax, 31           # Convert to leading zeros
        mov (=result), eax
    }

    return result;
}

# Fast check if power of 2
frame isPowerOfTwo(n: int) ret bool {
    if (n <= 0) { return false; }
    return (n & (n - 1)) == 0;
}

frame main() ret int {
    printf("Leading zeros in 1: %d\n", countLeadingZeros(1));
    printf("Leading zeros in 16: %d\n", countLeadingZeros(16));
    printf("Leading zeros in 255: %d\n", countLeadingZeros(255));

    printf("\nPower of 2 checks:\n");
    printf("isPowerOfTwo(1) = %d\n", isPowerOfTwo(1));
    printf("isPowerOfTwo(16) = %d\n", isPowerOfTwo(16));
    printf("isPowerOfTwo(15) = %d\n", isPowerOfTwo(15));
    printf("isPowerOfTwo(64) = %d\n", isPowerOfTwo(64));

    return 0;
}

sections.instructions:
Write `swapXor(a: *int, b: *int)` using inline assembly and XOR to swap two integers without a temporary variable.

XOR swap: a ^= b; b ^= a; a ^= b;

Test by swapping 10 and 20.

sections.solution:
import [printf] from "std/c.bpl";

frame swapXor(a: *int, b: *int) {
    asm("intel") {
        mov eax, [a]      # Load *a
        mov ebx, [b]      # Load *b
        xor eax, ebx      # a ^= b
        xor ebx, eax      # b ^= a
        xor eax, ebx      # a ^= b
        mov [a], eax      # Store back
        mov [b], ebx
        [ "eax", "ebx" ]
    }
}

frame main() ret int {
    local x: int = 10;
    local y: int = 20;

    printf("Before: x=%d, y=%d\n", x, y);
    swapXor(&x, &y);
    printf("After: x=%d, y=%d\n", x, y);

    return 0;
}
